# The same hero, twice: as a class, and as a dictionary
class Hero:
    def __init__(self, name, health):
        self.name = name
        self.health = health

nova = Hero("Nova", 10)
kai = {"name": "Kai", "health": 9}

def heal(health, amount):
    return min(health + amount, 10)

print(nova.name, nova.health)
print(kai["name"], kai["health"])
print(heal(kai["health"], 3))
